```go
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"log"

	"github.com/tidwall/gjson"
)

// ParseGoSourceFile returns the Avro schema for a given Go struct.
func ParseGoSourceFile(file string) (string, error) {
	if _, err := parser.ParseFile(token.NewFileSet(), file, nil, 0); err != nil {
		return "", fmt.Errorf("failed to parse Go source: %w", err)
	}

	var astNode interface{}
	ast.Inspect(ast.NewFileParser(nil), func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.TypeSpec:
			for _, field := range n.Fields.List {
				if gjson.GetBytes(field.Names[0].Name, "name") == "$struct" {
					astNode = field.Type // Assuming the struct is defined as $struct Type
					break
				}
			}
		default:
			continue
		}
		return false
	})

	structType, ok := astNode.(*ast.StructType)
	if !ok {
		return "", fmt.Errorf("could not find a struct definition")
	}

	avroSchema := structToAvroSchema(structType)
	return avroSchema, nil
}

func structToAvroSchema(structType *ast.StructType) string {
	var fields []gjson.Result

	for i, field := range structType.Fields.List {
		fieldName := field.Names[0].Name
		fieldType := gjson.GetBytes(field.Type.String(), fieldName).String()
		fields = append(fields, gjson.Result{
			Key:   fieldName,
			Value: fieldType,
		})
	}

	return fmt.Sprintf(`{"namespace":"com.example","type":"record","fields":%s}`, gjson.Encode(fields))
}

func main() {
	fileName := "example.go"
	structName := "YourStructName"

	schema, err := ParseGoSourceFile(fileName)
	if err != nil {
		log.Fatalf("Error parsing Go source: %v", err)
	}

	fmt.Println(schema)
}
```

### How to Use:

1. **Compile the Program**: Run `go build` in your terminal to compile the program.
2. **Run the Program**: Execute the compiled binary with the path to the Go source file and the struct name you're interested in.
3. **Check Output**: The generated AVRO schema will be printed to the console or saved to a file if provided.

### Example Usage:

Suppose you have a Go source file `example.go` with the following content:

```go
package example

type MyStruct struct {
	Name string
	Age  int
}
```

And another file `main.go` containing the following code:

```go
